// Deterministische Kontrolle nach dem Modell. Die Schwelle ist ein Vorschlag und wird mit E4 kalibriert.
const SCHWELLE = 0.7;
const ERLAUBT = ['inklusive', 'zusatzleistung', 'unklar'];
const KATEGORIEN = ['A', 'B', 'C', 'E'];
const LEER = ['', 'NULL', 'NONE', 'N/A', '-'];
const norm = s => String(s ?? '').toLowerCase().replace(/[*_`|]/g, ' ').replace(/\s+/g, ' ').trim();
const vertrag = norm($('Vertragstext lesen').first().json.data);
const ticketId = $('Kunde bestimmen und Eingang normalisieren').first(0).json.ticketId;
const kundeId = $('Kunde bestimmen und Eingang normalisieren').first(0).json.kundeId;
const klasse = $('Anfrage klassifizieren').first(0).json.output?.klasse ?? '';
const items = $input.all();
const quellen = items.length > 0 ? items : [{ json: {} }];
return quellen.map(item => {
  const a = item.json.output ?? {};
  const zitat = norm(a.zitat);
  const zitatOk = zitat.length >= 15 && vertrag.includes(zitat);
  const rawKat = String(a.kategorie ?? '').trim().toUpperCase();
  const kat = KATEGORIEN.includes(rawKat) ? rawKat : null;
  const gruende = [];
  if (!ERLAUBT.includes(a.urteil)) gruende.push('Urteil fehlt oder ungültig');
  if (a.urteil === 'unklar') gruende.push('Urteil unklar');
  if (a.urteil !== 'unklar' && !zitatOk) gruende.push('Zitat nicht wörtlich im Vertrag gefunden');
  if (!(Number(a.sicherheit) >= SCHWELLE)) gruende.push('Sicherheit unter Schwelle');
  if (a.urteil === 'zusatzleistung' && !kat) gruende.push('Kategorie fehlt oder ungültig');
  if (!kat && !LEER.includes(rawKat)) gruende.push('Kategorie ungültig: ' + rawKat);
  return { json: {
    ticketId, kundeId, klasse,
    urteil: a.urteil ?? null, fundstelle: a.fundstelle ?? null, zitat: a.zitat ?? null, kategorie: kat,
    begruendung: a.begruendung ?? null, sicherheit: a.sicherheit ?? null,
    zitatOk, eskalieren: gruende.length > 0, grund: gruende.join('; '),
    preis: null,
    preisHinweis: 'Preis nach Regel (Stundensatz mal Aufwand), Stundensatz und Aufwand noch nicht angebunden'
  } };
});

// Kontingent gegenprüfen: rechnet der Code, nicht das Modell. Quelle: Sheet Kontingentkonten Capstone, Tab Kunde <ID>.
const basis = $('Urteil prüfen').first().json;
const konto = {};
for (const item of $input.all()) {
  const r = item.json;
  if (r['Feld'] !== undefined && r['Feld'] !== null && String(r['Feld']).trim() !== '') konto[String(r['Feld']).trim()] = r['Wert'];
}
const num = v => {
  if (typeof v === 'number') return v;
  const s = String(v ?? '').trim();
  return s === '' ? NaN : Number(s.replace(',', '.'));
};
const iso = v => {
  if (typeof v === 'number') return new Date(Math.round((v - 25569) * 86400000)).toISOString().slice(0, 10);
  const s = String(v ?? '').trim();
  if (s.length >= 10 && s[4] === '-' && s[7] === '-') return s.slice(0, 10);
  const p = s.split('.');
  if (p.length === 3 && p[2].length === 4) return p[2] + '-' + p[1].padStart(2, '0') + '-' + p[0].padStart(2, '0');
  return '';
};
const heute = $now.toISODate();
const einheit = String(konto['Einheit'] ?? '');
const gesamt = num(konto['Gesamt']);
const verbraucht = num(konto['Verbraucht']);
const restSheet = num(konto['Rest']);
const von = iso(konto['Periode von']);
const bis = iso(konto['Periode bis']);
const maxKatA = num(konto['Max. Aufwand Kategorie A (in Einheit)']);
const rest = gesamt - verbraucht;
const k = { einheit, gesamt, verbraucht, rest, periodeVon: von, periodeBis: bis, regel: String(konto['Regel'] ?? '') };
let status, text;
if (!Number.isFinite(gesamt) || !Number.isFinite(verbraucht) || !von || !bis) {
  status = 'konto_unlesbar'; text = 'Kontingentkonto nicht lesbar oder unvollständig';
} else if (Number.isFinite(restSheet) && Math.abs(restSheet - rest) > 0.01) {
  status = 'konto_unplausibel'; text = 'Rest im Sheet weicht von Gesamt minus Verbraucht ab';
} else if (heute < von || heute > bis) {
  status = 'periode_abgelaufen'; text = 'Heute liegt außerhalb der Periode ' + von + ' bis ' + bis;
} else if (einheit === 'Seiten') {
  status = 'seiten_info'; text = 'Seitenkontingent (gilt nur für das Einlesen neuer Dokumente): Rest ' + rest + ' von ' + gesamt + ' Seiten, Seitenzahl der Anfrage nicht ermittelt';
} else if (basis.kategorie === 'C') {
  status = 'nicht_im_kontingent'; text = 'Kategorie C wird nie auf das Kontingent gebucht';
} else if (rest <= 0) {
  status = 'aufgebraucht'; text = 'Kontingent aufgebraucht (Rest ' + rest + ' ' + einheit + ')';
} else if (basis.kategorie === 'B') {
  status = 'aufwand_offen'; text = 'Rest ' + rest + ' von ' + gesamt + ' ' + einheit + ', den Aufwand der Kategorie B kalkuliert ein Mitarbeiter';
} else if (Number.isFinite(maxKatA)) {
  const nach = Math.round((rest - maxKatA) * 10) / 10;
  k.geschaetzterVerbrauchMax = maxKatA;
  k.restNachAnfrage = nach;
  status = nach < 0 ? 'knapp' : 'ausreichend';
  text = 'Rest ' + rest + ' von ' + gesamt + ' ' + einheit + ', diese Änderung höchstens ' + maxKatA + ', danach ' + nach + ' (' + status + ')';
} else {
  status = 'konto_unlesbar'; text = 'Höchstaufwand der Kategorie A fehlt im Konto';
}
k.status = status;
const blockt = ['konto_unlesbar', 'konto_unplausibel', 'periode_abgelaufen', 'aufgebraucht', 'knapp'];
const eskKontingent = blockt.includes(status);
// Regel (Knut): Kategorie A ist inklusive, solange das Kontingent voraussichtlich reicht. Reicht es nicht, ist es eine Zusatzleistung der Kategorie B.
// Gilt nur für Stunden- oder Budgetkonten; beim Seitenkontingent (nur Dokumente) bleibt das Urteil des Modells.
const katA = einheit !== 'Seiten' && ['inklusive', 'zusatzleistung'].includes(basis.urteil) && (basis.kategorie === 'A' || (basis.urteil === 'inklusive' && !basis.kategorie));
let urteil = basis.urteil;
let kategorie = basis.kategorie;
let regel = '';
if (katA && ['aufgebraucht', 'knapp', 'periode_abgelaufen'].includes(status)) {
  urteil = 'zusatzleistung'; kategorie = 'B'; regel = 'Kontingent reicht voraussichtlich nicht, Kategorie A wird Zusatzleistung der Kategorie B';
} else if (katA && status === 'ausreichend') {
  urteil = 'inklusive'; kategorie = 'A';
}
// Vertragsgrenze, ab der der Kunde einer Änderung der Kategorie A vorab in Textform zustimmen muss (Feld „Kundenfreigabe ab (EUR)“).
// Das System schätzt keinen Aufwand und entscheidet nichts, es erinnert den Menschen, der den Aufwand einschätzt.
const freigabeAb = num(konto['Kundenfreigabe ab (EUR)']);
const istKatA = ['inklusive', 'zusatzleistung'].includes(basis.urteil) && (basis.kategorie === 'A' || (basis.urteil === 'inklusive' && !basis.kategorie));
const euro = n => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const kundenfreigabeText = istKatA && Number.isFinite(freigabeAb)
  ? 'Kunde muss vorab in Textform zustimmen, wenn der Aufwand voraussichtlich über ' + euro(freigabeAb) + ' EUR liegt (Vertrag, Kategorie A)'
  : '';
k.kundenfreigabeAb = Number.isFinite(freigabeAb) ? freigabeAb : null;
const gruende = [basis.grund, eskKontingent ? 'Kontingent: ' + text : '', regel].filter(Boolean).join('; ');
return [{ json: { ...basis, urteilModell: basis.urteil, kategorieModell: basis.kategorie, urteil, kategorie, kontingent: k, kontingentText: text, kundenfreigabeText, eskalieren: basis.eskalieren || eskKontingent, grund: gruende } }];

// Kunde bestimmen und Eingang normalisieren. Die Kunden-ID kommt nie vom Modell: bei Mails aus der Absenderadresse (erst genaue Adresse, dann Domain),
// beim Webhook-Test aus dem Body (kundeId oder absender). In beiden Fällen gilt sie nur, wenn sie im Kundenstamm steht, sonst bleibt kundeId leer (Ablehnung).
// Kundenstamm: ein Tab „Kunden“, Spalte „Absender“ mit Adressen und Domains, getrennt durch Komma, Semikolon oder Zeilenumbruch.
// ablehnungsgrund sagt, warum kein Kunde bestimmt wurde; die Ablehnung schreibt ihn ins Log.
const norm = s => String(s ?? '').trim();
let ein;
try {
  ein = $('Älteste Mail wählen und aufbereiten').first().json;
} catch (e) {
  const w = $('Anfrage per Webhook (Test)').first().json;
  const b = w.body ?? w;
  ein = { ticketId: b.ticketId, kundeId: b.kundeId, quelle: b.quelle, anfrage: b.anfrage, absender: b.absender, mailId: b.mailId };
}
const kunden = $input.all().map(i => i.json).filter(r => norm(r['Kunden-ID']) !== '');
const absender = kunden.flatMap(r => String(r['Absender'] ?? '').split(/[,;\n]/).map(norm).filter(Boolean)
  .map(eintrag => ({ eintrag: eintrag.toLowerCase(), id: norm(r['Kunden-ID']).toUpperCase() })));
const adresse = norm(ein.absender).toLowerCase();
const domain = adresse.split('@')[1] ?? '';
let id = '';
let anfrage = String(ein.anfrage ?? '');
let grund = '';
if (norm(ein.kundeId)) {
  id = norm(ein.kundeId).toUpperCase();
} else if (adresse) {
  const genau = absender.find(a => a.eintrag.includes('@') && !a.eintrag.startsWith('@') && a.eintrag === adresse);
  const dom = absender.find(a => { const d = a.eintrag.replace(/^@/, ''); return !d.includes('@') && d !== '' && (domain === d || domain.endsWith('.' + d)); });
  const treffer = genau ?? dom;
  id = treffer ? treffer.id : '';
  if (!treffer) grund = 'Absender steht nicht im Kundenstamm';
  // Eingetragene Tester (Kunden-ID TEST im Kundenstamm) nennen den Kunden im Betreff, z. B. "[Kunde B] Fehler im Export".
  // Nur für Tester, damit sich kein fremder Absender über den Betreff einen Kunden aussucht. Die Kennung wird entfernt, das Modell sieht den Kunden nicht.
  if (id === 'TEST') {
    const kennung = /\[\s*Kunde\s+([A-Za-z0-9]+)\s*\]\s*/i;
    const m = anfrage.split('\n')[0].match(kennung);
    id = m ? m[1].toUpperCase() : '';
    if (m) anfrage = anfrage.replace(kennung, '');
    else grund = 'Tester ohne [Kunde X] im Betreff';
  }
} else {
  grund = 'Weder Absender noch Kunden-ID angegeben';
}
const k = kunden.find(r => norm(r['Kunden-ID']).toUpperCase() === id);
const dateiId = k ? norm(k['Vertragsdatei-ID']) : '';
const kontingentTab = k ? norm(k['Kontingent-Tab']) : '';
const ok = id !== 'TEST' && Boolean(k) && dateiId !== '' && kontingentTab !== '';
if (!ok && !grund) grund = k ? 'Kunde ' + id + ' im Kundenstamm unvollständig (Vertragsdatei oder Kontingent-Tab fehlt)' : 'Kunde ' + id + ' steht nicht im Kundenstamm';
return [{ json: {
  ticketId: norm(ein.ticketId) || ('AUTO-' + $execution.id),
  kundeId: ok ? id : '',
  quelle: norm(ein.quelle) || 'Test',
  anfrage,
  mailId: norm(ein.mailId),
  dateiId: ok ? dateiId : '',
  kontingentTab: ok ? kontingentTab : '',
  ablehnungsgrund: ok ? '' : grund
}, pairedItem: { item: 0 } }]; // ohne Zuordnung liefert $('…').first() in späteren Knoten nichts (Lauf 611)

// Mail aus dem Ordner Agent in das Eingangsformat bringen. Die Kunden-ID wird erst danach im Kundenstamm nachgeschlagen.
// Der Outlook-Knoten liefert bis zu 25 Mails ohne feste Reihenfolge; verarbeitet wird die älteste, damit der Ordner der Reihe nach abläuft.
// Eine Mail pro Lauf: die Nodes danach lesen mit .first() und setzen genau einen Fall voraus.
// shortcut: nur die ersten 25 Mails des Ordners werden verglichen, bei größerem Rückstau eine sortierte Abfrage nachrüsten.
const m = $input.all().map(i => i.json).reduce((a, b) => (String(b.receivedDateTime ?? '') < String(a.receivedDateTime ?? '') ? b : a));
const betreff = String(m.subject ?? '');
const roh = String(m.body?.content ?? m.bodyPreview ?? '');
const istHtml = String(m.body?.contentType ?? '').toLowerCase() === 'html' || /<[a-z][\s\S]*>/i.test(roh);
const text = istHtml
  ? roh.replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<script[\s\S]*?<\/script>/gi, ' ')
      .replace(/<br\s*\/?>|<\/p>|<\/div>|<\/tr>|<\/li>/gi, '\n').replace(/<[^>]+>/g, ' ')
      .replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&')
  : roh;
const anfrage = (betreff + '\n\n' + text).replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n\n').trim();
const absender = String(m.from?.emailAddress?.address ?? m.sender?.emailAddress?.address ?? '').toLowerCase();
return [{ json: { anfrage, absender, quelle: 'Outlook', mailId: m.id } }];

// Übergabe an den Sub-Workflow „Capstone Slack-Ende“. Erst nach Log und Verschieben: eine Mail erzeugt höchstens eine Karte.
// Technische Fehler und Ablehnungen haben keinen slackWeg und bleiben nur im Protokoll.
const e = $('Ergebnis vereinheitlichen').first().json;
if (!e.slackWeg) return [];
const anfrage = $('Kunde bestimmen und Eingang normalisieren').isExecuted ? $('Kunde bestimmen und Eingang normalisieren').first(0).json.anfrage : '';
return [{ json: {
  slackWeg: e.slackWeg, ticketId: e.ticketId, kundeId: e.kundeId, klasse: e.klasse ?? '', grund: e.grund ?? '',
  urteil: e.urteil ?? null, kategorie: e.kategorie ?? null, sicherheit: e.sicherheit ?? null, begruendung: e.begruendung ?? null,
  fundstelle: e.fundstelle ?? null, zitatOk: e.zitatOk ?? null, kontingentText: e.kontingentText ?? '', kundenfreigabeText: e.kundenfreigabeText ?? '',
  klasseBegruendung: $('Anfrage klassifizieren').isExecuted ? ($('Anfrage klassifizieren').first(0).json.output?.begruendung ?? '') : '',
  anfrage, hauptAusfuehrung: String($execution.id)
} }];
